#include <bits/stdc++.h>
using namespace std;

static bool isWs(char c) { return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f'; }

int main() {
    string in;
    char chunk[1 << 16];
    size_t got;
    while ((got = fread(chunk, 1, sizeof chunk, stdin)) > 0) in.append(chunk, got);
    vector<string_view> tok;
    for (size_t i = 0; i < in.size();) {
        while (i < in.size() && isWs(in[i])) i++;
        size_t j = i;
        while (j < in.size() && !isWs(in[j])) j++;
        if (j > i) tok.emplace_back(in.data() + i, j - i);
        i = j;
    }
    int m = stoi(string(tok[0]));
    unordered_map<string_view, int> id;
    id.reserve(4 * m + 4);
    auto get = [&](string_view s) {
        auto it = id.find(s);
        if (it != id.end()) return it->second;
        int x = (int)id.size();
        id.emplace(s, x);
        return x;
    };
    vector<pair<int, int>> edges(m);
    for (int i = 0; i < m; i++) edges[i] = {get(tok[1 + 2 * i]), get(tok[2 + 2 * i])};
    int start = get(tok[1 + 2 * m]), target = get(tok[2 + 2 * m]);
    int V = (int)id.size();
    // Outgoing links per page (what get_links returns), in input order.
    vector<int> head(V + 1, 0), adj(m);
    for (auto &e : edges) head[e.first + 1]++;
    for (int i = 0; i < V; i++) head[i + 1] += head[i];
    vector<int> fill(head.begin(), head.end() - 1);
    for (auto &e : edges) adj[fill[e.first]++] = e.second;
    // BFS: the first time target is dequeued, its distance is the fewest clicks.
    vector<int> dist(V, -1), q;
    q.reserve(V);
    q.push_back(start);
    dist[start] = 0;
    for (size_t i = 0; i < q.size(); i++) {
        int u = q[i];
        if (u == target) { printf("%d\n", dist[u]); return 0; }
        for (int k = head[u]; k < head[u + 1]; k++)
            if (dist[adj[k]] < 0) { dist[adj[k]] = dist[u] + 1; q.push_back(adj[k]); }
    }
    puts("-1");
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    static boolean isWs(byte c) { return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == 0x0B || c == '\f'; }

    public static void main(String[] args) throws IOException {
        byte[] in = System.in.readAllBytes();
        // Names are compared as raw bytes, so ISO-8859-1 strings preserve equality exactly.
        List<String> tok = new ArrayList<>();
        for (int i = 0; i < in.length;) {
            while (i < in.length && isWs(in[i])) i++;
            int j = i;
            while (j < in.length && !isWs(in[j])) j++;
            if (j > i) tok.add(new String(in, i, j - i, StandardCharsets.ISO_8859_1));
            i = j;
        }
        int m = Integer.parseInt(tok.get(0));
        HashMap<String, Integer> id = new HashMap<>(4 * m + 4);
        int[] from = new int[m], dest = new int[m];
        for (int i = 0; i < m; i++) {
            from[i] = id.computeIfAbsent(tok.get(1 + 2 * i), k -> id.size());
            dest[i] = id.computeIfAbsent(tok.get(2 + 2 * i), k -> id.size());
        }
        int start = id.computeIfAbsent(tok.get(1 + 2 * m), k -> id.size());
        int target = id.computeIfAbsent(tok.get(2 + 2 * m), k -> id.size());
        int V = id.size();
        // Outgoing links per page (what get_links returns), in input order.
        int[] head = new int[V + 1], adj = new int[m];
        for (int i = 0; i < m; i++) head[from[i] + 1]++;
        for (int i = 0; i < V; i++) head[i + 1] += head[i];
        int[] fill = Arrays.copyOf(head, V);
        for (int i = 0; i < m; i++) adj[fill[from[i]]++] = dest[i];
        // BFS: the first time target is dequeued, its distance is the fewest clicks.
        int[] dist = new int[V], q = new int[V];
        Arrays.fill(dist, -1);
        int qh = 0, qt = 0;
        q[qt++] = start;
        dist[start] = 0;
        while (qh < qt) {
            int u = q[qh++];
            if (u == target) { System.out.println(dist[u]); return; }
            for (int k = head[u]; k < head[u + 1]; k++)
                if (dist[adj[k]] < 0) { dist[adj[k]] = dist[u] + 1; q[qt++] = adj[k]; }
        }
        System.out.println(-1);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
)

func isWs(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f'
}

func main() {
	in, _ := io.ReadAll(os.Stdin)
	var tok [][]byte
	for i := 0; i < len(in); {
		for i < len(in) && isWs(in[i]) {
			i++
		}
		j := i
		for j < len(in) && !isWs(in[j]) {
			j++
		}
		if j > i {
			tok = append(tok, in[i:j])
		}
		i = j
	}
	m, _ := strconv.Atoi(string(tok[0]))
	id := make(map[string]int32, 2*m+2)
	get := func(s []byte) int32 {
		if x, ok := id[string(s)]; ok {
			return x
		}
		x := int32(len(id))
		id[string(s)] = x
		return x
	}
	from, dest := make([]int32, m), make([]int32, m)
	for i := 0; i < m; i++ {
		from[i], dest[i] = get(tok[1+2*i]), get(tok[2+2*i])
	}
	start, target := get(tok[1+2*m]), get(tok[2+2*m])
	V := len(id)
	// Outgoing links per page (what get_links returns), in input order.
	head := make([]int32, V+1)
	for _, f := range from {
		head[f+1]++
	}
	for i := 0; i < V; i++ {
		head[i+1] += head[i]
	}
	fill := append([]int32(nil), head[:V]...)
	adj := make([]int32, m)
	for i, f := range from {
		adj[fill[f]] = dest[i]
		fill[f]++
	}
	// BFS: the first time target is dequeued, its distance is the fewest clicks.
	dist := make([]int32, V)
	for i := range dist {
		dist[i] = -1
	}
	q := []int32{start}
	dist[start] = 0
	for i := 0; i < len(q); i++ {
		u := q[i]
		if u == target {
			fmt.Println(dist[u])
			return
		}
		for k := head[u]; k < head[u+1]; k++ {
			if v := adj[k]; dist[v] < 0 {
				dist[v] = dist[u] + 1
				q = append(q, v)
			}
		}
	}
	fmt.Println(-1)
}
